it("pages through rows created in the same instant without skipping or repeating", async () => {
  const org = await createTenant("same-instant-issues");
  vi.useFakeTimers({ toFake: ["Date"] });
  try {
    vi.setSystemTime(new Date(Date.UTC(2026, 2, 1, 9, 0)));
    for (let index = 0; index < 7; index += 1) {
      const number = await issueRepo.nextIssueNumber(org.org.id, org.project.id);
      await issueRepo.insertIssue(
        issueInput(org.org.id, org.project.id, { title: `Imported ${index}` }),
        org.userIds.owner,
        number,
      );
    }
  } finally {
    vi.useRealTimers();
  }

  const everything = await issueRepo.listIssues({
    orgId: org.org.id,
    limit: 100,
    cursor: null,
  });
  const expected = everything.items.map((row) => row.id);
  expect(expected).toHaveLength(7);

  for (const limit of [1, 2, 3, 6]) {
    const walked: string[] = [];
    let cursor: string | null = null;
    do {
      const page = await issueRepo.listIssues({ orgId: org.org.id, limit, cursor });
      walked.push(...page.items.map((row) => row.id));
      cursor = page.nextCursor;
    } while (cursor !== null);

    expect(walked).toEqual(expected);
  }
});

